import React, { useEffect, useState } from 'react';
import {
    Button, Modal, ModalHeader, ModalBody, 
    ModalFooter, Form, FormGroup, Label, Input 
} from 'reactstrap';

const CursoList = () => {
    const [cursos, setCursos] = useState([]);
    const [modalOpen, setModalOpen] = useState(false);
    const [cursoEditar, setCursoEditar] = useState(null);

    useEffect(() => {
        fetchCursos();
    }, []);

    const fetchCursos = () => {
        fetch('https://paginas-web-cr.com/Api/apis/ListaCurso.php')
            .then(respuesta => respuesta.json())
            .then((datosrepuesta) => {
                setCursos(datosrepuesta.data);
            })
            .catch(error => {
                console.error('Error al cargar:', error);
            });
    };

    const toggleEditModal = (curso) => {
        setCursoEditar(curso);
        setModalOpen(!modalOpen);
    };

    const handleChange = (e) => {
        const { id, value } = e.target;
        setCursoEditar({ ...cursoEditar, [id]: value });
    };

    const guardar = async () => {
        // lógica para guardar el curso editado
    };

    return (
        <div className='container'>
            <br /><br /><br />
            <Button color='dark' onClick={() => toggleEditModal({})}> 
                Agregar
            </Button>

            <table className="table table-info">
                <thead>
                    <tr>
                        <th scope="col">Acciones</th>
                        <th scope="col">Id</th>
                        <th scope="col">Nombre</th>
                        <th scope="col">Descripcion</th>
                        <th scope="col">Tiempo</th>
                        <th scope="col">Usuario</th>
                    </tr>
                </thead>
                <tbody id="datos">
                    {cursos.map(curso => (
                        <tr key={curso.id}>
                            <td>
                                <Button color="warning" onClick={() => toggleEditModal(curso)}>Editar</Button>
                            </td>
                            <td>{curso.id}</td>
                            <td>{curso.nombre}</td>
                            <td>{curso.descripcion}</td>
                            <td>{curso.tiempo}</td>
                            <td>{curso.usuario}</td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <Modal isOpen={modalOpen}>
                <ModalHeader>Modal Curso</ModalHeader>
                <ModalBody>
                    <FormGroup>
                        <Label for="nombre">Nombre</Label>
                        <Input type='text' id='nombre' value={cursoEditar?.nombre || ''} onChange={handleChange} />
                    </FormGroup>
                    <FormGroup>
                        <Label for="descripcion">Descripción</Label>
                        <Input type='text' id='descripcion' value={cursoEditar?.descripcion || ''} onChange={handleChange} />
                    </FormGroup>
                    <FormGroup>
                        <Label for="tiempo">Tiempo</Label>
                        <Input type='text' id='tiempo' value={cursoEditar?.tiempo || ''} onChange={handleChange} />
                    </FormGroup>
                    <FormGroup>
                        <Label for="usuario">Usuario</Label>
                        <Input type='text' id='usuario' value={cursoEditar?.usuario || ''} onChange={handleChange} />
                    </FormGroup>
                </ModalBody>
                <ModalFooter>
                    <Button color='primary' onClick={guardar}>Guardar</Button>
                    <Button color='secondary' onClick={() => toggleEditModal(null)}>Cerrar</Button>
                </ModalFooter>
            </Modal>
        </div>
    );
}

export default CursoList;
